INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00989', NULL, NULL, 0, NULL, NULL, 0, NULL, 2017, NULL, '車椅子の勾配基準は法律で決まってる！スロープがあれば大丈夫と思ってませんか？', NULL, NULL, NULL, 'ja', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://welserch.com/disability/wheelchair/wheelchair-koubai', '2026-09-16', NULL, NULL, 1, 'co1', 'JP', 'First-person wheelchair-user authorship, evidenced in the retrieved bytes rather than inferred from venue (D-0178): the author writes 「車椅子ユーザーである私がスロープの勾配の本音をお伝えしていきながら」 — "I, a wheelchair user, will tell you the honest truth about ramp gradients". The site self-describes as 福祉の専門家や当事者たちが発信する福祉情報サイト — published by welfare professionals AND 当事者 (people with lived experience). Named individual: 白倉栄一 (Shirakura Eiichi), 車椅子ライフデザイナー.', 'lived_experience_publication', NULL, 'GREY', 'VERIFIED', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', NULL, NULL, 1, NULL, 'スロープ＝車椅子で利用可能と決めつけてはいけない / 法律でスロープの勾配基準は1/12（1/8）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (85, 'JP', '高齢者、障害者等の移動等の円滑化の促進に関する法律 (Barrier-Free Law) — 建築物移動等円滑化基準, ramp gradient provisions', NULL, 'REFERENCE-ONLY', NULL, 'R12: a code value met in a secondary source and DELIBERATELY NOT COPIED INTO THE CORPUS. REF-00989 states 勾配は、12分の1を超えないこと with 1/15 outdoors and 8分の１ for rises of 16cm or less, attributing all three to the Barrier-Free Law. The law itself was NOT retrieved, so under CLAUDE.md rule 5 (point, do not copy) and the 2026-08-12 REFERENCE-ONLY ruling this lead records WHICH DOCUMENT TO FETCH and holds no values. It matters beyond bookkeeping: the Japanese figure the corpus would otherwise inherit second-hand is the baseline BOTH Co-1 extractions audit, so the corpus holds a lived-experience assessment of a legal figure it has never read.', '2026-09-16 23:27', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (33, 'accessible-circulation-geometry', 'UK', 'EN', 2, 'co1', 'intrinsic', 'Habinteg wheelchair housing design guide ramp gradient', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'Publication page retrieved (habinteg.org.uk): landing page only, guide sold via CAE, NO gradient in the retrievable bytes. The 1:15/1:12 figures the search index surfaced were in NO page retrieved and are therefore not recorded anywhere in this batch. Foundations ramp guidance, which appears to carry them, returned HTTP 403. R14: RETRIEVAL FAILURE, not absence.', 0, 'States a gradient, restated from Part M / BS 8300 rather than derived. Habinteg is disability-led, so the document is Co-1-adjacent; the NUMBER will not be its own.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (34, 'accessible-circulation-geometry', 'UK', 'EN', 2, 'co2', 'intrinsic', 'RCOT housing adaptations without delay ramp gradient occupational therapy', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'RETRIEVED AND READ IN FULL (4.8MB PDF, 40pp, text extracted locally). Adaptations without Delay (RCOT + Housing LIN) states NO ramp gradient anywhere. Ramps appear as a demand category and as a bullet delegating "Ramp design" to Foundations. PRIOR FALSIFIED: the UK OT professional body carries no gradient in its flagship adaptations guidance.', 0, 'Practice guidance citing the statutory maximum; possibly a preference for shallower. Best chance of a Co-2 working value.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (35, 'accessible-circulation-geometry', 'US', 'EN', 2, 'co1', 'intrinsic', 'Paralyzed Veterans of America ramp slope wheelchair users guidance', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'ZERO-YIELD for the target class: no PVA-published ramp guidance surfaced; results were commercial vendors, Wikipedia and ADA restatements (T3, navigation only). R14: WRONG INDEX rather than genuine absence - a general index does not reach PVA publication pages. Direct site retrieval is owed.', 0, 'PVA is a disabled-led membership organisation; may carry a stated preference distinct from ADA.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (36, 'accessible-circulation-geometry', 'US', 'EN', 2, 'co2', 'intrinsic', 'AOTA home modification ramp slope occupational therapy practice', NULL, 'web', 'scoping', 'none', 8, 8, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'AOTA Practice Guidelines for Home Modifications sit behind library.aota.org (member access) - R14: RETRIEVAL FAILURE. One retrievable OT-practitioner source found and read (HMOTA), staged as a candidate rather than admitted pending tier adjudication.', 0, 'Cites ADA 1:12; may prefer 1:16 or 1:20 for self-propulsion.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (37, 'accessible-circulation-geometry', 'UK', 'EN', 2, 'co1', 'intrinsic', 'Scope OR "Disability Rights UK" OR "Leonard Cheshire" ramp too steep wheelchair users barrier report', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'PRIOR CONFIRMED and thinner than expected. Scope physical accessibility guidelines retrieved in full: ramps appear once, deferring to Part M, and NO gradient is stated. No UK DPO document stating or contesting a gradient was reached. R14: GENUINE ABSENCE for the stated-gradient question; WRONG INDEX for the inadequacy question, which surfaced forum threads rather than publications.', 0, 'Positional/experiential, no number. Likely an inadequacy finding (R7).');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (38, 'accessible-circulation-geometry', 'DE', 'DE', 5, 'national_fw', 'national', 'Rollstuhl Rampe Neigung barrierefrei Selbsthilfe Behindertenverband Empfehlung', NULL, 'web', 'scoping', 'none', 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'Prior partly right, and it surfaced what the EN pass did not: a gradient set CONDITIONED ON PROPULSION MODE. Commercial portals carried it (T3, navigation only); the authoritative home is the DGUV publication, retrieved and admitted as REF-00988 at 6% maximum - materially shallower than the ADA 1:12 already in this corpus.', 0, 'DIN 18040 restated (6%); DPO framing rather than derivation.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (39, 'accessible-circulation-geometry', 'FR', 'FR', 2, 'co1', 'intrinsic', 'pente rampe fauteuil roulant accessibilité APF France Handicap recommandation', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'ZERO-YIELD for the target class: every result a commercial ramp vendor or ERP-compliance consultancy; no APF France Handicap publication page reached. R14: WRONG INDEX. A NEAR-MISS WORTH RECORDING: the search summary asserted APF report figures (an incident share, a conformity share, a March 2026 report). NOTHING was retrieved to support them and they are NOT recorded; one cited report may not exist at all. That is CLAUDE.md 5(c) in live form - fluent, unsourced, and one copy-paste from the corpus.', 0, 'Arrete 2014 (5%) restated; APF is a large DPO with position papers.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (40, 'accessible-circulation-geometry', 'NL', 'NL', 2, 'co1', 'intrinsic', 'rolstoel hellingbaan helling percentage toegankelijkheid Ieder(in) richtlijn', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'PRIOR EXCEEDED, yield Flemish rather than Dutch. Handboek Toegankelijkheid Publieke Gebouwen (Gelijke Kansen in Vlaanderen en Inter) carries a RISE-CONDITIONED gradient table and, verbatim from the persisted bytes, the acceptability criterion itself: "Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt." NOT ADMITTED: the retrieved bytes carry no publication date anywhere and add-source requires --year; inventing one is the 5(c) failure. Staged as a candidate; a dated carrier is owed.', 0, 'Dutch guidance restates NEN/Bbl; possible practical rule of thumb.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (41, 'accessible-circulation-geometry', 'ES', 'ES', 2, 'co1', 'intrinsic', 'pendiente rampa silla de ruedas accesibilidad CERMI ONCE recomendación autonomía', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'ZERO-YIELD for the target class, same shape as FR: vendors and compliance consultancies, no CERMI or ONCE publication page reached. R14: WRONG INDEX. Owed and recorded: CTE DB-SUA carries a length-conditioned structure (10%/8%/6%) matching the Flemish and French pattern, and a Chilean T2 manual surfaced as a lead.', 0, 'CTE DB-SUA restated; CERMI is the Spanish disability platform.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (42, 'accessible-circulation-geometry', 'JP', 'JA', 1, 'co1', 'intrinsic', '車椅子 スロープ 勾配 バリアフリー 障害者団体 自走 限界', NULL, 'web', 'scoping', 'none', 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:25', 'THE Co-1 LEG SUCCEEDED HERE AND ONLY HERE. Two sources written BY wheelchair users were reached, which no English query returned at any tier. Admitted REF-00989 (first-person authorship evidenced in the bytes); a second, a cervical-SCI author writing in his own voice, is staged rather than admitted. No DPI Japan document reached - owed. This execution is the POSITIVE CONTROL for batch 08 R14 claim that the PubMed Co-1 zero is a VENUE fact: same subject, different venue and language, not empty.', 0, 'Barrier-free Law restates 1:12; DPI Japan may carry position material.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-16-resea-REF-00989-MOB', 'REF-00989', 'MOB', 'Manual wheelchair users accustomed to their chair; the author himself (車椅子ライフデザイナー, writing in the first person) plus his generalisation to 一般の乗りなれている車椅子ユーザー', 1, 'PARTIAL', 'PARTIAL, not EXACT, and the reason is the population boundary rather than the evidence type. The served population MOB includes powered-chair users, people newly using a chair, people with less upper-body strength and people who fatigue; this source speaks explicitly and only for self-propelling users ACCUSTOMED to their chair, and says so - which is why the 1/12 judgment cannot be read across MOB. n=1 first-person, generalised by the author. NOT graded PROXY: the author IS a member of the population served, which is the distinction PROXY exists to mark (children, general population, no participants). Under CRPD Art 4.3 that co-primacy is the source of its strength; the narrowness is a scope limit on the claim, not a discount on the witness.', '2026-09-16 23:27', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', 'REF-00989', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (130, 'REF-00988', 1, NULL, NULL, NULL, NULL, 1, 'Deutsche Gesetzliche Unfallversicherung e.V.', NULL, 'author', '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', NULL);
