INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (38, 'REF-00988', '2026-09-16 23:25', 'session_2026-09-16-research-batch-09-ramp-gradient-co1');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (42, 'REF-00989', '2026-09-16 23:25', 'session_2026-09-16-research-batch-09-ramp-gradient-co1');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (69, 40, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Helling — Niveauverschillen — Handboek Toegankelijkheid Publieke Gebouwen (Gelijke Kansen in Vlaanderen en Inter). Rise-conditioned gradient table (to 10cm: max 10%, length 1m; 10-25cm: 8,3%, 3m; 25-50cm: 6,25%, 8m; more than 50cm: 5%, 10m) AND the stated acceptability criterion "Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt", with the reason: "Hoe groter het hoogteverschil, hoe zachter de helling moet zijn, omdat men gedurende een langere tijd een inspanning moet leveren". HYPOTHESIS PER R15. BLOCKED SPECIFICALLY: the retrieved bytes carry no publication date, so --year cannot be evidenced. Resolve by retrieving a dated carrier (the Flemish Stedenbouwkundige verordening toegankelijkheid Art. 19 as published) and re-describing from THAT source.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (70, 42, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'まっつん (Mattun), cervical spinal cord injury wheelchair user, personal site 障害者のドクゼツ本音とーく, 2018-06-25: first-person account of gradients he can and cannot climb (1/12 about 5 degrees, "I can just about get up this with bare hands"; 1/4 about 14 degrees in a basketball wheelchair). HYPOTHESIS PER R15. Not admitted because the adjudication is open and not mine to make silently: governance/tier-system.md defines Co-1 as "disability-led lived-experience publications - DPOs, named-org ... outputs", and an individual self-published blog is lived experience without being a named-org output. Either Co-1 widens to individual first-person testimony or this is grey carrying a lived-experience flag. Owner/adjudication call, and it recurs for every blog by a disabled person - which on this parameter is where the testimony actually is.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (71, 36, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Home Modification Occupational Therapy Alliance (HMOTA), Karen Koch, "How to Design a Wheelchair Ramp", 2018-01-13: states "The slope should be 1:12" and "If it were a power wheelchair we could get away with a 1:8 slope", both as practice judgment with no code cited. HYPOTHESIS PER R15. Valuable because it conditions gradient on PROPULSION MODE, as the German and Flemish sources do and the ADA does not. Not admitted: HMOTA is a practitioner alliance blog, not an OT professional-body CPG, so Co-2 does not fit as defined; tier placement needs the practice/Co-3 encoding governance/tier-system.md defers to the audit rework.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (72, 33, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Foundations (national body for home improvement agencies in England), "Guidance For Ramp Adaptations" — the document RCOT Adaptations without Delay delegates ramp design to, and the apparent source of the 1:15/1:12 length-conditioned figures the search index surfaced. RETRIEVAL BLOCKED: HTTP 403 on direct fetch. HYPOTHESIS PER R15 - nothing about its content is asserted here, because nothing was read. Resolve by a different retrieval route; it is the UK gradient authority this pass could not reach.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (73, 36, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'AOTA, Occupational Therapy Practice Guidelines for Home Modifications (library.aota.org). RETRIEVAL BLOCKED: member-gated. HYPOTHESIS PER R15. This is the US Co-2 CPG the R1 pass is supposed to reach and could not; whether it states a ramp gradient is UNKNOWN and is not guessed at here.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (74, 41, 'accessible-circulation-geometry', NULL, 'REHOME', 'Corporación Ciudad Accesible (CL), "Ciudades y Espacios para Todos: Manual de Accesibilidad Universal", Capítulo III Accesibilidad en la Edificación. Surfaced on the ES query; a disability-accessibility NGO manual, so a genuine T2/Co-1-adjacent candidate, but the slug pass was scoped to ES-Spain and this is Chile. REHOME to the ES/LatAm jurisdiction pass rather than dropped.', NULL, NULL, NULL, 0, NULL, NULL, 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00988', 'accessible-circulation-geometry', '7', '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00989', 'accessible-circulation-geometry', '8', '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:24', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (19, 'REF-00988', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'DE', NULL, 'numerical', '6', '%', 'Rampenläufe dürfen maximal eine Neigung von 6 % aufweisen; dies wird auch von Fußgängern als angenehm empfunden.', 'Kapitel 4.3, Anforderungen an Rampen', NULL, 'committee_assertion', 'REF-00988', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'GERMAN CEILING IS MATERIALLY SHALLOWER THAN THE ADA CEILING ALREADY IN THIS CORPUS: 6% against REF-00987 1:12 (8.33%). Both are committee assertions in the regulatory stratum, neither anchors at full strength (CLAUDE.md §6), and they disagree by about a factor of 1.4 on the same parameter. relation=none is literal, not a default: the document states 6% absolutely and names no reference for it. It lists ArbStättV, ASR V 3a.2, Landesbauordnungen and DIN 18040-1 as Weiterfuehrende Informationen but attributes the figure to none of them, so nothing is guessed at DIN. [VERBATIM-EXEMPT: The persisted artefact is a FlateDecode-compressed PDF (874,252 bytes, sha256 7f53490bc8a43838...), so no substring of its rendered text occurs in its bytes. Read off sheet 2 of that exact artefact via pypdf and reproduced character for character. The DGUV HTML surface was retrieved specifically to obtain a byte-checkable carrier and does NOT contain the sentence - it is a navigation page - so the PDF is the only carrier that exists.]', '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (20, 'REF-00989', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'qualitative', 'wheelchair users accustomed to their chair can manage 1/12; 1/8 is passable only with a run-up', NULL, '実際に、一般の乗りなれている車椅子ユーザーであれば、1/12は大丈夫かと思います。1/8となると、助走があればいけると思います。', 'スロープの勾配の基準は車椅子ユーザー目線で', NULL, 'participatory_finding', 'REF-00989', NULL, NULL, NULL, 'The author is himself a manual wheelchair user and writes in the first person; the judgment is explicitly about 一般の乗りなれている車椅子ユーザー - wheelchair users accustomed to their chair. It is NOT a claim about wheelchair users in general, and explicitly not about new, fatigued or less physically able users.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'LIVED-EXPERIENCE ASSESSMENT OF A LEGAL FIGURE - what the R1 pass exists to reach, and what no PubMed query returned for this parameter. The author does not derive 1/12; he judges the Barrier-Free Law figure against what he can actually do, qualified by user experience and by run-up. Graded finding, not claim, because db.py refuses an audited_against edge on a claim row: a row auditing subjects against a baseline asserts no absolute value of its own. Under the owner statement of 2026-09-16 this is THRESHOLD material rather than dose-response. Co-primary with T1 under CRPD Art 4.3; not down-weighted for being self-published, since venue is not evidence quality (R5 reasoning by analogy).', '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (21, 'REF-00989', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'JP', NULL, 'qualitative', 'steeper than 1/8: independent self-propulsion near-impossible however long the ramp', NULL, '8分の１より勾配がある場合は、いくらスロープがあっても車椅子を自走で上るのは不可能に近いです。', 'スロープ＝車椅子で利用可能と決めつけてはいけない', NULL, 'participatory_finding', 'REF-00989', NULL, NULL, NULL, 'First-person wheelchair-user judgment. Speaks to self-propulsion (自走) specifically, so it is silent on assisted or powered use - the same distinction the German and Flemish sources draw structurally and the ADA does not.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE CLOSEST THING THE CORPUS NOW HOLDS TO A STATED THRESHOLD OF ACCEPTABILITY, and it comes from lived experience rather than from research or from a code. The 2026-09-16 owner statement records that the dose-response evidence has a degenerate solution - both curves monotonic, so "best" resolves to 0 degrees, which is not a ramp - and that the missing half is a threshold of acceptability no admitted source supplied. This row supplies one, for self-propulsion: above one-in-eight it is not that the ramp is uncomfortable, it is that it cannot be climbed. It is a BOUNDARY, not a recommended value: it says where use fails, not what should be built, and must not be read as asserting that one-in-eight is acceptable. The Barrier-Free Law permits 8分の１ for rises of 16cm or less, and this row places the feasibility boundary at exactly that figure. This row could not be written at all until the verbatim normaliser was fixed the same day: full-width １ was extracted as a digit by db.py and deleted by the normaliser, so no CJK numeral could pass.', '2026-09-16 23:27', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', '2026-09-16 23:27', 'session_2026-09-16-research-batch-09-ramp-gradient-co1', 'finding', NULL);
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (17, 20, 'audited_against', NULL, '1/12', 'standard', 'named', NULL, '1/12は大丈夫かと思います', NULL, '2026-09-16 23:26', 'session_2026-09-16-research-batch-09-ramp-gradient-co1');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (18, 21, 'audited_against', NULL, '8分の１', 'standard', 'named', NULL, '8分の１より勾配がある場合は', NULL, '2026-09-16 23:27', 'session_2026-09-16-research-batch-09-ramp-gradient-co1');